// Funnel status is read-only. It is checked before Serve because issuing a
// Serve command on a Funnel-owned port would silently change public/private
// behavior even though GameEngine never intends to configure Funnel.
let funnel_status = run_cli(cli, &["funnel", "status", "--json"])?;
if json_has_https_443_configuration(&parse_optional_json(&funnel_status.stdout)?) {
    return Err(TailscalePublicationError::ExistingConfigurationConflict);
}

let serve_status = run_cli(cli, &["serve", "status", "--json"])?;
let serve_json = parse_optional_json(&serve_status.stdout)?;
let existing_root = https_443_root_proxy(&serve_json);
let any_existing_443 = json_has_https_443_configuration(&serve_json);

new:
// Serve status carries both the private proxy configuration and the
// AllowFunnel flags used by the same local serve configuration. Refuse a
// public-enabled mapping without invoking the `tailscale funnel` command at
// all: GameEngine never enables, disables, resets, or otherwise operates
// Funnel.
let serve_status = run_cli(cli, &["serve", "status", "--json"])?;
let serve_json = parse_optional_json(&serve_status.stdout)?;
if json_allows_funnel_on_https_443(&serve_json) {
    return Err(TailscalePublicationError::ExistingConfigurationConflict);
}
let existing_root = https_443_root_proxy(&serve_json);
let any_existing_443 = json_has_https_443_configuration(&serve_json);
